create or replace function private.broadcast_result_change()returns trigger language plpgsql security definer set search_path=pg_catalog,public,private,realtime as $$declare v_event uuid;v_club uuid;v_version bigint;v_kind text;begin if tg_table_name='result_confirmations'then select r.event_id,r.club_id,r.version into v_event,v_club,v_version from public.result_revisions rr join public.match_results r on r.id=rr.result_id where rr.id=new.result_revision_id;v_kind:='confirmation.changed';else v_event:=new.event_id;v_club:=new.club_id;v_version:=new.version;v_kind:='result.changed';end if;perform realtime.send(jsonb_build_object('schemaVersion',1,'eventId',v_event,'clubId',v_club,'aggregateVersion',v_version,'occurredAt',now(),'payload',jsonb_build_object('eventType',v_kind,'entityId',case when tg_table_name='result_confirmations'then new.result_revision_id else new.id end)),v_kind,'club:'||v_club::text||':event:'||v_event::text||':operations',true);return new;end$$;
create trigger match_result_broadcast after insert or update on public.match_results for each row execute function private.broadcast_result_change();create trigger result_confirmation_broadcast after insert on public.result_confirmations for each row execute function private.broadcast_result_change();
